import logging
from taf.collectors.aashell_log.factory import AaShellLogFactory
from taf.collectors.core import core

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class aashell_log(core):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def create_aashell_log_collector(self,
                                     name,
                                     tool,
                                     options=None,
                                     target_file_name=None,
                                     timeout=None):

        """
        Create Aashell Collector from given configuration. This collector executes the AaShell command "log" and
        collects the resulting file

            :param str name: name of collector
            :param str tool: name of aashell_cli
            :param str options: (optional) aashell log command options (except for '-z'), default: '-a'
            :param str target_file_name: (optional) file name part of the path under which the aashell_log zip file is
                                        stored locally during collect_collectors, default: "aashell_log_files.tgz"
            :param int timeout: (optional) aashell log command timeout in seconds, default value is 60

        For more example please refer:
        https://confluence.int.net.nokia.com/display/CV/Aashell_Log_Collectors_Example

        For more detail on Collectors please refer:
        https://confluence.int.net.nokia.com/display/CV/Collectors
        """

        configuration = {'name': name}
        for parameter_name, parameter_value in locals().items():
            if parameter_name in ["options", "target_file_name", "timeout"]:
                if parameter_value is not None:
                    configuration[parameter_name] = int(parameter_value) \
                        if parameter_name in ["timeout"] else parameter_value
        existing_arguments = {'tool': self.get_alias_value(tool)}
        logger.info("Creating Aashell Log Collector with alias name :" + name)
        aashell = AaShellLogFactory().create(configuration=configuration, existing_arguments=existing_arguments)
        logger.info("Aashell Log Collector created successfully")
        self.set_alias(name, aashell)
